/**
 * ArtifactPreview Component
 * Displays artifact content with tabs for code and preview
 * Following the project's component patterns and design system
 */

import React, { useCallback, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import cx from 'classnames';
import { Button } from '@memori.ai/ui';
import { ArtifactData, ArtifactTab } from '../../types/artifact.types';
import { Code, Eye as PreviewIcon } from 'lucide-react';
import Snippet from '../../../Snippet/Snippet';
import { Medium } from '@memori.ai/memori-api-client/dist/types';
import { renderMsg, sanitizeMsg } from '../../../../helpers/message';
import { attachInPageAnchorNavigation } from '../../utils/inPageAnchors';

const ArtifactPreview: React.FC<{
  artifact: ArtifactData;
  activeTab: ArtifactTab;
}> = ({ artifact, activeTab }) => {
  const { t } = useTranslation();
  const detachAnchorsRef = useRef<(() => void) | null>(null);

  const handleIframeLoad = useCallback(
    (event: React.SyntheticEvent<HTMLIFrameElement>) => {
      detachAnchorsRef.current?.();
      const doc = event.currentTarget.contentDocument;
      detachAnchorsRef.current = doc ? attachInPageAnchorNavigation(doc) : null;
    },
    []
  );

  useEffect(() => () => detachAnchorsRef.current?.(), []);

  /**
   * Render preview content based on MIME type
   */
  const renderPreview = useCallback(() => {
    switch (artifact.mimeType) {
      case 'html':
        return (
          <iframe
            className="memori-artifact-preview-iframe"
            srcDoc={artifact.content}
            style={{
              width: '100%',
              height: '100%',
              border: 'none',
              borderRadius: '6px',
            }}
            title={`${artifact.title} Preview`}
            scrolling="auto"
            onLoad={handleIframeLoad}
          />
        );

      case 'markdown': {
        const { text: renderedMarkdown } = renderMsg(
          artifact.content,
          false,
          'Reasoning...',
          false
        );
        return (
          <div
            className="memori-artifact-preview-markdown"
            dangerouslySetInnerHTML={{
              __html: renderedMarkdown,
            }}
          />
        );
      }

      default:
        return (
          <div
            className="memori-artifact-preview-text"
            dangerouslySetInnerHTML={{
              __html: sanitizeMsg(artifact.content),
            }}
          />
        );
    }
  }, [artifact, handleIframeLoad]);

  const mapArtifactMimeTypeToSnippetMimeType = useCallback(
    (mimeType: string) => {
      switch (mimeType) {
        case 'javascript':
          return 'text/javascript';
        case 'typescript':
          return 'text/ecmascript';
        case 'html':
          return 'application/xml';
        case 'css':
          return 'text/css';
        case 'json':
          return 'application/json';
        case 'python':
          return 'text/x-python';
        case 'bash':
          return 'application/x-sh';
        case 'cpp':
        case 'csharp':
          return 'text/x-c++src';
        case 'php':
          return 'application/x-php';
        case 'sql':
          return 'text/x-sql';
        case 'ruby':
          return 'text/x-ruby';
        default:
          return 'text/plain';
      }
    },
    []
  );

  const hasPreview =
    artifact.mimeType === 'html' ||
    artifact.mimeType === 'markdown' ||
    artifact.mimeType === 'svg';

  return (
    <div className="memori-artifact-preview">
      {/* Content */}
      <div className="memori-artifact-content">
        {/* Code Tab */}
        <div
          className={cx('memori-artifact-tab-content', {
            'memori-artifact-tab-content--active':
              activeTab === 'code' || !hasPreview,
          })}
        >
          <div className="memori-artifact-code">
            <Snippet
              showCopyButton={false}
              medium={
                {
                  mediumID: artifact.id,
                  mimeType: mapArtifactMimeTypeToSnippetMimeType(
                    artifact.mimeType
                  ),
                  content: artifact.content,
                  title: artifact.title,
                  creationTimestamp: artifact.timestamp.toISOString(),
                  creationName: 'System',
                  lastChangeTimestamp: artifact.timestamp.toISOString(),
                  lastChangeName: 'System',
                } as Medium
              }
            />
          </div>
        </div>

        {/* Preview Tab */}
        {hasPreview && (
          <div
            className={cx('memori-artifact-tab-content', {
              'memori-artifact-tab-content--active': activeTab === 'preview',
            })}
          >
            <div className="memori-artifact-preview-content">
              {renderPreview()}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ArtifactPreview;
