import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import cx from 'classnames';
import {
  ExpertReference,
  Medium,
  Memori,
  Message,
  Tenant,
  User,
} from '@memori.ai/memori-api-client/dist/types';
import { Props as MemoriProps } from '../MemoriWidget/MemoriWidget';
import { getResourceUrl } from '../../helpers/media';
import {
  User as UserIcon,
  Bot,
  Languages,
  HelpCircle,
  Copy,
  Code,
  Bug,
  Check,
} from 'lucide-react';
import { Tooltip } from '@memori.ai/ui';
import { usePressTooltip } from '../../helpers/usePressTooltip';
import { useDrawerPortalContainer } from '../SideDrawer/useDrawerPortalContainer';
import FeedbackButtons from '../FeedbackButtons/FeedbackButtons';
import { useTranslation } from 'react-i18next';
import { Button } from '@memori.ai/ui';
import WhyThisAnswer from '../WhyThisAnswer/WhyThisAnswer';
import {
  parseDocumentAttachmentsFromMessage,
  stripHTML,
  stripOutputTags,
  stripReasoningTags,
} from '../../helpers/utils';
import { extractReasoning } from '../../helpers/reasoning';
import ReasoningBlock from '../ReasoningBlock/ReasoningBlock';
import { isHtmlWebLink } from '../MediaWidget/MediaItemWidget.utils';
import {
  renderMsg,
  sanitizeMsg,
  stripAttachmentTags,
  stripAllInternalTags,
} from '../../helpers/message';
import { enhanceBubbleCodeBlocks } from '../../helpers/enhanceBubbleCodeBlocks';
import { getExposedSourcesCount } from '../../helpers/sourcesCount';
import { Expandable, Modal } from '@memori.ai/ui';
import memoriApiClient from '@memori.ai/memori-api-client';
const ASSET_URL_PATTERN = /https?:\/\/\S*\/api\/v\d+\/asset\/\S+/gi;

const sanitizeRawCopyText = (text: string) =>
  sanitizeMsg(
    stripAttachmentTags(text)
      .replace(/<\/?documents?\b[^>]*>/gi, '')
      .replace(/<documents?\b[^>]*\/>/gi, '')
      .replace(/<\/?attachments?\b[^>]*>/gi, '')
      .replace(/<attachments?\b[^>]*\/>/gi, '')
      .replace(ASSET_URL_PATTERN, '')
      .trim()
  );
import ArtifactHandler from '../MemoriArtifactSystem/components/ArtifactHandler/ArtifactHandler';

/** Same reset window as ShareButton copy feedback */
const COPY_FEEDBACK_MS = 2500;

const GeneratedByAIMark: React.FC<{
  label: string;
  container?: HTMLElement | null;
}> = ({ label, container }) => {
  const pressTooltip = usePressTooltip();

  return (
    <Tooltip
      placement="bottom"
      content={label}
      container={container ?? undefined}
      className="memori-chat--bubble-action-icon memori-chat--bubble-action-icon--ai"
      {...pressTooltip.tooltipProps}
      slotProps={{
        positioner: {
          className: 'memori-chat--bubble-addon-tooltip-positioner',
          ...pressTooltip.positionerProps,
        },
      }}
    >
      <span
        ref={pressTooltip.anchorRef}
        className="memori-chat--bubble-addon-tooltip-trigger memori-chat--bubble-ai-icon"
        role="img"
        aria-label={label}
        {...pressTooltip.pressTriggerProps}
      >
        <Bot aria-hidden />
      </span>
    </Tooltip>
  );
};

// Always import and load MathJax
import { installMathJax } from '../../helpers/utils';
import MediaWidget from '../MediaWidget/MediaWidget';
import { Props as MediaWidgetProps } from '../MediaWidget/MediaWidget';

// Import MathJax types
declare global {
  interface Window {
    MathJax?: {
      typesetPromise?: (elements: string[]) => Promise<void>;
    };
  }
}

export interface Props {
  message: Message;
  memori: Memori;
  sessionID: string;
  tenant?: Tenant;
  baseUrl?: string;
  apiUrl?: string;
  client?: ReturnType<typeof memoriApiClient>;
  showFeedback?: boolean;
  showWhyThisAnswer?: boolean;
  showCopyButton?: boolean;
  showTranslationOriginal?: boolean;
  simulateUserPrompt?: (msg: string) => void;
  showAIicon?: boolean;
  useMathFormatting?: boolean;
  isFirst?: boolean;
  userAvatar?: MemoriProps['userAvatar'];
  user?: User;
  experts?: ExpertReference[];
  showFunctionCache?: boolean;
  showReasoning?: boolean;
  usageHtml?: string;
  isChatlogPanel?: boolean;
  showDates?: boolean;
  codeMimeTypes?: string[];
  translateTo?: string;
  customMediaRenderer?: MediaWidgetProps['customMediaRenderer'];
  /** Play enter motion. Omit for history already present on first render. */
  animateEnter?: boolean;
}

const ChatBubble: React.FC<Props> = ({
  message,
  memori,
  tenant,
  baseUrl,
  apiUrl,
  client,
  sessionID,
  showFeedback,
  showWhyThisAnswer = true,
  showCopyButton = true,
  showTranslationOriginal = false,
  simulateUserPrompt,
  showAIicon = true,
  useMathFormatting = false,
  user,
  userAvatar,
  experts,
  showFunctionCache = false,
  showReasoning = false,
  usageHtml = '',
  isChatlogPanel = false,
  showDates = false,
  codeMimeTypes = [],
  translateTo,
  customMediaRenderer,
  animateEnter = false,
}) => {
  const { t, i18n } = useTranslation();
  const lang = i18n.language || 'en';
  const [showingWhyThisAnswer, setShowingWhyThisAnswer] = useState(false);
  const [openFunctionCache, setOpenFunctionCache] = useState(false);
  const [copyStatus, setCopyStatus] = useState<{
    plain: 'idle' | 'success' | 'error';
    raw: 'idle' | 'success' | 'error';
    functionCache: 'idle' | 'success' | 'error';
  }>({ plain: 'idle', raw: 'idle', functionCache: 'idle' });
  const copyResetTimers = useRef<{
    plain: ReturnType<typeof setTimeout> | null;
    raw: ReturnType<typeof setTimeout> | null;
    functionCache: ReturnType<typeof setTimeout> | null;
  }>({
    plain: null,
    raw: null,
    functionCache: null,
  });
  const [addonOpen, setAddonOpen] = useState(false);
  const bubbleContainerRef = useRef<HTMLDivElement | null>(null);
  const { ref: drawerPortalRef, container: drawerPortalContainer } =
    useDrawerPortalContainer();
  const setBubbleContainer = useCallback(
    (node: HTMLDivElement | null) => {
      bubbleContainerRef.current = node;
      drawerPortalRef(node);
    },
    [drawerPortalRef]
  );
  const assistantContentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!addonOpen) return;

    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (target && bubbleContainerRef.current?.contains(target)) return;
      setAddonOpen(false);
    };

    document.addEventListener('pointerdown', onPointerDown);
    return () => document.removeEventListener('pointerdown', onPointerDown);
  }, [addonOpen]);

  // Initialize MathJax on component mount
  useEffect(() => {
    if (typeof window !== 'undefined' && !window.MathJax) {
      installMathJax();
    }
  }, []);

  // Clean text by removing attachment blocks before rendering
  const cleanText = stripAttachmentTags(message.translatedText || message.text);
  const reasoningExtract = message.fromUser
    ? {
        content: '',
        complete: true,
        // Expandable handles length for user messages.
        remaining: cleanText,
        hasReasoning: false,
      }
    : extractReasoning(cleanText);
  const { text: renderedText } = renderMsg(
    reasoningExtract.remaining,
    useMathFormatting,
    t('reasoning') || 'Reasoning...',
    false
  );
  // User bubbles stay plain text (exact typed content); only assistant uses markdown HTML.
  const plainText = message.fromUser
    ? cleanText
    : stripHTML(stripOutputTags(renderedText));
  const copyText = plainText;
  const shouldShowCopyButtons =
    showCopyButton &&
    (!!plainText?.length ||
      !!(message.fromUser ? message.text : reasoningExtract.remaining)?.length);
  const shouldShowCopyRawButton =
    shouldShowCopyButtons &&
    !!message.text?.length &&
    plainText !== message.text;
  const rawMessageText = sanitizeMsg(
    stripAllInternalTags(
      message.fromUser
        ? message.text || ''
        : stripReasoningTags(message.text || '')
    )
  );
  const showReasoningBlock =
    !message.fromUser && showReasoning && reasoningExtract.hasReasoning;
  const hasAnswerBody =
    reasoningExtract.remaining.trim().length > 0 || !!usageHtml;
  const copiedLabel = t('copied') || 'Copied';
  // Opt-in via showDates (same contract as v8): hidden unless the consumer asks.
  // When enabled, show time only (HH:MM) — no calendar date.
  const formattedTimestamp =
    showDates && message.timestamp
      ? (() => {
          const date = new Date(
            message.timestamp.endsWith('Z')
              ? message.timestamp
              : `${message.timestamp}Z`
          );
          if (Number.isNaN(date.getTime())) {
            return null;
          }
          try {
            return new Intl.DateTimeFormat(i18n.language || 'it', {
              hour: '2-digit',
              minute: '2-digit',
            }).format(date);
          } catch {
            return null;
          }
        })()
      : null;

  // Format function cache content
  const functionCacheData = message.media?.filter(
    m => String(m.properties?.functionCache) === 'true'
  );
  const shouldShowFunctionCacheButton =
    !message.fromUser && showFunctionCache && !!functionCacheData?.length;

  useLayoutEffect(() => {
    if (typeof window !== 'undefined' && !message.fromUser) {
      const timer = setTimeout(() => {
        if (window.MathJax && window.MathJax.typesetPromise) {
          try {
            const elements = document.querySelectorAll(
              '.memori-chat--bubble-content'
            );
            if (elements.length > 0) {
              // Salva la posizione di scroll corrente
              const scrollContainer = document.querySelector(
                '.memori-chat--history'
              );
              const currentScrollTop = scrollContainer?.scrollTop || 0;
              const currentScrollHeight = scrollContainer?.scrollHeight || 0;

              window.MathJax.typesetPromise(['.memori-chat--bubble-content'])
                .then(() => {
                  // Ripristina la posizione di scroll dopo il rendering MathJax
                  if (scrollContainer) {
                    const newScrollHeight = scrollContainer.scrollHeight;
                    const heightDifference =
                      newScrollHeight - currentScrollHeight;
                    scrollContainer.scrollTop =
                      currentScrollTop + heightDifference;
                  }
                })
                .catch(err =>
                  console.error('MathJax typesetting failed:', err)
                );
            }
          } catch (error) {
            console.error('Error during MathJax typesetting:', error);
          }
        }
      }, 100);

      return () => clearTimeout(timer);
    }
  }, [cleanText, message.fromUser, renderedText]);

  useEffect(() => {
    if (message.fromUser || !assistantContentRef.current) return;
    return enhanceBubbleCodeBlocks(assistantContentRef.current, {
      copy: t('copy') || 'Copy',
      copied: t('copied') || 'Copied',
    });
  }, [renderedText, message.fromUser, t]);

  useEffect(() => {
    return () => {
      (
        Object.keys(copyResetTimers.current) as Array<
          'plain' | 'raw' | 'functionCache'
        >
      ).forEach(key => {
        const timer = copyResetTimers.current[key];
        if (timer) {
          clearTimeout(timer);
          copyResetTimers.current[key] = null;
        }
      });
    };
  }, []);

  const functionCacheCopyText =
    functionCacheData
      ?.map(f => `${f.title}\n\n${f.content}`)
      .join('\n\n---\n\n') ?? '';

  const clearCopyReset = (type: 'plain' | 'raw' | 'functionCache') => {
    if (copyResetTimers.current[type]) {
      clearTimeout(copyResetTimers.current[type]!);
      copyResetTimers.current[type] = null;
    }
  };

  const scheduleCopyReset = (type: 'plain' | 'raw' | 'functionCache') => {
    clearCopyReset(type);
    copyResetTimers.current[type] = setTimeout(() => {
      setCopyStatus(prev => ({ ...prev, [type]: 'idle' }));
      copyResetTimers.current[type] = null;
    }, COPY_FEEDBACK_MS);
  };

  const handleCopyClick = async (
    type: 'plain' | 'raw' | 'functionCache',
    text: string
  ) => {
    if (!text?.length) return;
    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        throw new Error('Clipboard unavailable');
      }
      setCopyStatus(prev => ({ ...prev, [type]: 'success' }));
      scheduleCopyReset(type);
    } catch (err) {
      console.error('Copy failed', err);
      setCopyStatus(prev => ({ ...prev, [type]: 'error' }));
      scheduleCopyReset(type);
    }
  };

  // Check if initial is a string (status message) or boolean (legacy)
  const initialStatus =
    typeof message.initial === 'string' ? message.initial : null;
  const showInitialDivider = message.initial === true && !initialStatus;

  // Check if this is a system error message
  const isSystemError = message.emitter === 'system';

  const renderAssistantAvatar = () => (
    <picture
      className="memori-chat--bubble-avatar"
      title={
        !!message.emitter?.length && !!memori.enableBoardOfExperts
          ? message.emitter
          : memori.name
      }
    >
      <img
        className="memori-chat--bubble-avatar-img memori-motion-fade-in"
        alt={
          !!message.emitter?.length && !!memori.enableBoardOfExperts
            ? message.emitter
            : memori.name
        }
        src={
          !!message.emitter?.length &&
          !!memori.enableBoardOfExperts &&
          experts?.find(e => e.name === message.emitter)
            ? `${new URL(apiUrl ?? '/').origin}/api/v1/memoriai/memori/avatar/${
                experts.find(e => e.name === message.emitter)?.expertMemoriID
              }`
            : memori.avatarURL && memori.avatarURL.length > 0
              ? getResourceUrl({
                  type: 'avatar',
                  tenantID: tenant?.name,
                  resourceURI: memori.avatarURL,
                  baseURL: baseUrl,
                  apiURL: apiUrl,
                })
              : getResourceUrl({
                  tenantID: tenant?.name,
                  type: 'avatar',
                  baseURL: baseUrl || 'https://www.aisuru.com',
                  apiURL: apiUrl,
                })
        }
        onError={e => {
          e.currentTarget.src =
            memori.avatarURL && memori.avatarURL.length > 0
              ? getResourceUrl({
                  type: 'avatar',
                  tenantID: tenant?.name,
                  resourceURI: memori.avatarURL,
                  baseURL: baseUrl,
                })
              : getResourceUrl({
                  tenantID: tenant?.name,
                  type: 'avatar',
                  baseURL: baseUrl,
                });

          e.currentTarget.onerror = null;
        }}
      />
    </picture>
  );

  const renderUserAvatar = () => {
    if (
      (!!userAvatar && typeof userAvatar === 'string') ||
      (!userAvatar && !!user?.avatarURL?.length)
    ) {
      return (
        <picture className="memori-chat--bubble-avatar">
          <img
            className="memori-chat--bubble-avatar-img memori-motion-fade-in"
            alt={user?.userName ?? 'User'}
            src={userAvatar ?? user?.avatarURL}
          />
        </picture>
      );
    }

    if (userAvatar) {
      return <div className="memori-chat--bubble-avatar">{userAvatar}</div>;
    }

    return (
      <div className="memori-chat--bubble-avatar">
        <UserIcon />
      </div>
    );
  };

  if (initialStatus) {
    const isLoginSuccess = message.contextVars?.LOGIN_STATUS === 'success';
    return (
      <div
        className={cx('memori-chat--bubble-status-message', {
          'memori-chat--bubble-status-message--success': isLoginSuccess,
        })}
        role="status"
      >
        <span className="memori-chat--bubble-status-message-content">
          {isLoginSuccess && (
            <Check
              className="memori-chat--bubble-status-message-check"
              size={16}
              strokeWidth={2.5}
              aria-hidden
            />
          )}
          {initialStatus}
        </span>
      </div>
    );
  }

  // Render system error messages as red warning messages
  if (isSystemError) {
    return (
      <div
        className={cx('memori-chat--bubble-container memori-chat-scroll-item', {
          'memori-chat--bubble-from-user': false,
          'memori-motion-enter-up': animateEnter,
        })}
      >
        {renderAssistantAvatar()}
        <div className="memori-chat--bubble memori-chat--bubble-status-message-error">
          <div className="memori-chat--bubble-message ">
            {sanitizeMsg(cleanText)}
          </div>
        </div>
      </div>
    );
  }

  const shouldShowTimestampInAddon = !!formattedTimestamp;
  const bubbleAddonTooltipProps = {
    container: drawerPortalContainer ?? undefined,
    slotProps: {
      positioner: {
        className: 'memori-chat--bubble-addon-tooltip-positioner',
      },
    },
  };
  const exposedSourcesCount = getExposedSourcesCount(message);
  const whyThisAnswerSourcesLabel =
    exposedSourcesCount == null
      ? undefined
      : exposedSourcesCount > 0
        ? t('whyThisAnswerSourcesCount', {
            count: exposedSourcesCount,
          })
        : t('whyThisAnswerNoSources');
  const shouldShowBubbleAddon =
    shouldShowTimestampInAddon ||
    shouldShowCopyButtons ||
    shouldShowFunctionCacheButton ||
    (message.generatedByAI && showAIicon) ||
    (showFeedback && simulateUserPrompt) ||
    (showTranslationOriginal &&
      message.translatedText &&
      message.translatedText !== message.text) ||
    (!message.fromUser &&
      message.questionAnswered &&
      apiUrl &&
      showWhyThisAnswer);

  const handleBubbleContainerClick = (
    event: React.MouseEvent<HTMLDivElement>
  ) => {
    if (!shouldShowBubbleAddon) return;
    if (
      typeof window !== 'undefined' &&
      window.matchMedia('(hover: hover) and (pointer: fine)').matches
    ) {
      return;
    }
    if (
      (event.target as Element | null)?.closest?.(
        '.memori-chat--bubble-addon, button, a, input, textarea, [role="button"]'
      )
    ) {
      return;
    }
    setAddonOpen(open => !open);
  };

  const topMediaWidgetLinks = (message?.media
    ?.filter(m => !m.properties?.functionSignature)
    ?.filter(m => isHtmlWebLink(m)) || []) as Medium[];

  const topMediaWidgetMedia = [
    ...(message?.media
      ?.filter(m => !m.properties?.functionSignature)
      ?.filter(
        m => !(codeMimeTypes.includes(m.mimeType) || isHtmlWebLink(m))
      ) || []),
    ...parseDocumentAttachmentsFromMessage(
      message.translatedText || message.text
    ).map((attachment, attachmentIndex): Medium & { type?: string } => ({
      mediumID: `doc_${Date.now()}_${attachmentIndex}_${Math.random()
        .toString(36)
        .substr(2, 9)}`,
      url: attachment.url,
      mimeType: attachment.type,
      title: attachment.filename,
      content: attachment.content,
      properties: { isDocumentAttachment: true },
      type: 'document',
    })),
  ];

  const codeMediaWidgetMedia =
    message?.media
      ?.filter(m => !m.properties?.functionSignature)
      ?.filter(m => codeMimeTypes.includes(m.mimeType)) || [];

  const hasAddonAfterTimestamp =
    shouldShowCopyButtons ||
    shouldShowFunctionCacheButton ||
    (message.generatedByAI && showAIicon) ||
    (showFeedback && simulateUserPrompt) ||
    (showTranslationOriginal &&
      message.translatedText &&
      message.translatedText !== message.text) ||
    (!message.fromUser &&
      message.questionAnswered &&
      apiUrl &&
      showWhyThisAnswer);

  const hasTopMedia =
    topMediaWidgetMedia.length > 0 || topMediaWidgetLinks.length > 0;

  const attachmentStrip = hasTopMedia ? (
    <div className="memori-chat--attachment-strip">
      <MediaWidget
        simulateUserPrompt={simulateUserPrompt}
        links={topMediaWidgetLinks}
        media={topMediaWidgetMedia}
        sessionID={sessionID}
        baseUrl={baseUrl}
        apiUrl={apiUrl}
        translateTo={translateTo}
        customMediaRenderer={customMediaRenderer}
        fromUser={message.fromUser}
      />
    </div>
  ) : null;

  return (
    <>
      {showInitialDivider && <div className="memori-chat--bubble-initial" />}
      <div
        ref={setBubbleContainer}
        className={cx('memori-chat--bubble-container memori-chat-scroll-item', {
          'memori-chat--bubble-from-user': !!message.fromUser,
          'memori-chat--with-addon':
            shouldShowBubbleAddon && (message.fromUser || hasAnswerBody),
          'memori-chat--addon-open':
            shouldShowBubbleAddon &&
            (message.fromUser || hasAnswerBody) &&
            addonOpen,
          'memori-motion-enter-up': animateEnter,
        })}
        onClick={handleBubbleContainerClick}
      >
        <div className="memori-chat--bubble-message-row">
          {!message.fromUser && renderAssistantAvatar()}

          {message.fromUser ? (
            <div className="memori-chat--user-block">
              {attachmentStrip}

              <div
                className={cx('memori-chat--bubble-shell', {
                  'memori-chat--bubble-shell--from-user': true,
                })}
              >
                <div
                  className={cx('memori-chat--bubble-anchor', {
                    'memori-chat--bubble-anchor--from-user': true,
                    'memori-chat--bubble-anchor--has-addon':
                      shouldShowBubbleAddon,
                  })}
                >
                  <div
                    className={cx('memori-chat--bubble', {
                      'memori-chat--user-bubble': true,
                      'memori-chat--with-addon':
                        shouldShowCopyButtons ||
                        (showFeedback && simulateUserPrompt),
                      'memori-chat--ai-generated': message.generatedByAI,
                      'memori-chat--with-feedback': showFeedback,
                    })}
                  >
                    <Expandable
                      className="memori-chat--bubble-content"
                      mode="characters"
                    >
                      <div
                        dir="auto"
                        className="memori-chat--bubble-content"
                        dangerouslySetInnerHTML={{
                          __html: sanitizeMsg(cleanText).replaceAll(
                            '\n',
                            '<br/>'
                          ),
                        }}
                      />
                    </Expandable>

                    {!!usageHtml && (
                      <div
                        className="memori-chat--usage-inside-bubble"
                        dangerouslySetInnerHTML={{ __html: usageHtml }}
                      />
                    )}
                  </div>

                  {shouldShowBubbleAddon && (
                    <div className="memori-chat--bubble-addon">
                      {shouldShowTimestampInAddon && (
                        <div className="memori-chat--bubble-timestamp-container">
                          <p className="memori-chat--bubble-timestamp">
                            {formattedTimestamp}
                          </p>
                          {hasAddonAfterTimestamp && (
                            <span className="memori-chat--bubble-timestamp-separator">
                              •
                            </span>
                          )}
                        </div>
                      )}
                      {shouldShowCopyButtons && (
                        <Tooltip
                          {...bubbleAddonTooltipProps}
                          placement="bottom"
                          content={
                            copyStatus.plain === 'success'
                              ? copiedLabel
                              : copyStatus.plain === 'error'
                                ? t('copyFailed')
                                : t('copy') || 'Copy'
                          }
                        >
                          <span className="memori-chat--bubble-addon-tooltip-trigger">
                            <Button
                              variant="ghost"
                              shape="circle"
                              type="button"
                              size="sm"
                              aria-label={
                                copyStatus.plain === 'success'
                                  ? String(copiedLabel)
                                  : copyStatus.plain === 'error'
                                    ? String(t('copyFailed'))
                                    : String(t('copy') || 'Copy')
                              }
                              className={cx(
                                'memori-chat--bubble-action-button',
                                'memori-share-button--copy-item',
                                {
                                  'memori-share-button--copy-item--success':
                                    copyStatus.plain === 'success',
                                  'memori-share-button--copy-item--error':
                                    copyStatus.plain === 'error',
                                }
                              )}
                              icon={
                                copyStatus.plain === 'success' ? (
                                  <Check
                                    className="memori-share-button--copy-icon"
                                    aria-hidden
                                    strokeWidth={2.5}
                                  />
                                ) : (
                                  <Copy
                                    className="memori-share-button--copy-icon"
                                    aria-hidden
                                  />
                                )
                              }
                              onClick={() => handleCopyClick('plain', copyText)}
                            />
                          </span>
                        </Tooltip>
                      )}

                      {shouldShowCopyRawButton && (
                        <Tooltip
                          {...bubbleAddonTooltipProps}
                          placement="bottom"
                          content={
                            copyStatus.raw === 'success'
                              ? copiedLabel
                              : copyStatus.raw === 'error'
                                ? t('copyFailed')
                                : t('copyRawCode') || 'Copy raw code'
                          }
                        >
                          <span className="memori-chat--bubble-addon-tooltip-trigger">
                            <Button
                              variant="ghost"
                              shape="circle"
                              type="button"
                              size="sm"
                              aria-label={
                                copyStatus.raw === 'success'
                                  ? String(copiedLabel)
                                  : copyStatus.raw === 'error'
                                    ? String(t('copyFailed'))
                                    : String(
                                        t('copyRawCode') || 'Copy raw code'
                                      )
                              }
                              className={cx(
                                'memori-chat--bubble-action-button',
                                'memori-share-button--copy-item',
                                {
                                  'memori-share-button--copy-item--success':
                                    copyStatus.raw === 'success',
                                  'memori-share-button--copy-item--error':
                                    copyStatus.raw === 'error',
                                }
                              )}
                              icon={
                                copyStatus.raw === 'success' ? (
                                  <Check
                                    className="memori-share-button--copy-icon"
                                    aria-hidden
                                    strokeWidth={2.5}
                                  />
                                ) : (
                                  <Code
                                    className="memori-share-button--copy-icon"
                                    aria-hidden
                                  />
                                )
                              }
                              onClick={() =>
                                handleCopyClick('raw', rawMessageText)
                              }
                            />
                          </span>
                        </Tooltip>
                      )}

                      {showFeedback && !!simulateUserPrompt && (
                        <FeedbackButtons
                          memori={memori}
                          className="memori-chat--bubble-feedback"
                          dropdown
                          onNegativeClick={msg => {
                            if (msg) simulateUserPrompt(msg);
                          }}
                        />
                      )}

                      {message.generatedByAI && showAIicon && (
                        <GeneratedByAIMark
                          label={String(t('generatedByAI'))}
                          container={drawerPortalContainer}
                        />
                      )}

                      {showTranslationOriginal &&
                        message.translatedText &&
                        message.translatedText !== message.text && (
                          <Tooltip
                            {...bubbleAddonTooltipProps}
                            placement="bottom"
                            content={`${
                              lang === 'it'
                                ? 'Testo originale'
                                : 'Original text'
                            }: ${stripAllInternalTags(message.text)}`}
                            className="memori-chat--bubble-action-icon memori-chat--bubble-action-icon--ai"
                          >
                            <span className="memori-chat--bubble-addon-tooltip-trigger">
                              <Button
                                variant="ghost"
                                shape="circle"
                                type="button"
                                size="sm"
                                className="memori-chat--bubble-action-button"
                                aria-label={
                                  lang === 'it'
                                    ? 'Testo originale'
                                    : 'Original text'
                                }
                                icon={<Languages aria-hidden />}
                              />
                            </span>
                          </Tooltip>
                        )}
                    </div>
                  )}
                </div>
              </div>

              {codeMediaWidgetMedia.length > 0 && (
                <MediaWidget
                  simulateUserPrompt={simulateUserPrompt}
                  media={codeMediaWidgetMedia}
                  sessionID={sessionID}
                  baseUrl={baseUrl}
                  apiUrl={apiUrl}
                  translateTo={translateTo}
                  customMediaRenderer={customMediaRenderer}
                  fromUser={message.fromUser}
                />
              )}
            </div>
          ) : (
            <div
              className={cx('memori-chat--bubble-shell', {
                'memori-chat--bubble-shell--from-user': !!message.fromUser,
              })}
            >
              {attachmentStrip}

              <div
                className={cx('memori-chat--bubble-anchor', {
                  'memori-chat--bubble-anchor--from-user': !!message.fromUser,
                  'memori-chat--bubble-anchor--has-addon':
                    shouldShowBubbleAddon && hasAnswerBody,
                })}
              >
                {showReasoningBlock && (
                  <ReasoningBlock
                    content={reasoningExtract.content}
                    complete={reasoningExtract.complete}
                  />
                )}

                {hasAnswerBody && (
                  <div
                    className={cx('memori-chat--bubble', {
                      'memori-chat--user-bubble': !!message.fromUser,
                      'memori-chat--with-addon':
                        shouldShowCopyButtons ||
                        (showFeedback && simulateUserPrompt),
                      'memori-chat--ai-generated': message.generatedByAI,
                      'memori-chat--with-feedback': showFeedback,
                    })}
                  >
                    <div
                      ref={assistantContentRef}
                      dir="auto"
                      className="memori-chat--bubble-content"
                      dangerouslySetInnerHTML={{ __html: renderedText }}
                    />

                    {!!usageHtml && (
                      <div
                        className="memori-chat--usage-inside-bubble"
                        dangerouslySetInnerHTML={{ __html: usageHtml }}
                      />
                    )}
                  </div>
                )}

                {hasAnswerBody && shouldShowBubbleAddon && (
                  <div className="memori-chat--bubble-addon">
                    {shouldShowTimestampInAddon && (
                      <div className="memori-chat--bubble-timestamp-container">
                        <p className="memori-chat--bubble-timestamp">
                          {formattedTimestamp}
                        </p>
                        {hasAddonAfterTimestamp && (
                          <span className="memori-chat--bubble-timestamp-separator">
                            •
                          </span>
                        )}
                      </div>
                    )}
                    {shouldShowCopyButtons && (
                      <Tooltip
                        {...bubbleAddonTooltipProps}
                        placement="bottom"
                        content={
                          copyStatus.plain === 'success'
                            ? copiedLabel
                            : copyStatus.plain === 'error'
                              ? t('copyFailed')
                              : t('copy') || 'Copy'
                        }
                      >
                        <span className="memori-chat--bubble-addon-tooltip-trigger">
                          <Button
                            variant="ghost"
                            shape="circle"
                            type="button"
                            size="sm"
                            aria-label={
                              copyStatus.plain === 'success'
                                ? String(copiedLabel)
                                : copyStatus.plain === 'error'
                                  ? String(t('copyFailed'))
                                  : String(t('copy') || 'Copy')
                            }
                            className={cx(
                              'memori-chat--bubble-action-button',
                              'memori-share-button--copy-item',
                              {
                                'memori-share-button--copy-item--success':
                                  copyStatus.plain === 'success',
                                'memori-share-button--copy-item--error':
                                  copyStatus.plain === 'error',
                              }
                            )}
                            icon={
                              copyStatus.plain === 'success' ? (
                                <Check
                                  className="memori-share-button--copy-icon"
                                  aria-hidden
                                  strokeWidth={2.5}
                                />
                              ) : (
                                <Copy
                                  className="memori-share-button--copy-icon"
                                  aria-hidden
                                />
                              )
                            }
                            onClick={() => handleCopyClick('plain', copyText)}
                          />
                        </span>
                      </Tooltip>
                    )}

                    {shouldShowCopyRawButton && (
                      <Tooltip
                        {...bubbleAddonTooltipProps}
                        placement="bottom"
                        content={
                          copyStatus.raw === 'success'
                            ? copiedLabel
                            : copyStatus.raw === 'error'
                              ? t('copyFailed')
                              : t('copyRawCode') || 'Copy raw code'
                        }
                      >
                        <span className="memori-chat--bubble-addon-tooltip-trigger">
                          <Button
                            variant="ghost"
                            shape="circle"
                            type="button"
                            size="sm"
                            aria-label={
                              copyStatus.raw === 'success'
                                ? String(copiedLabel)
                                : copyStatus.raw === 'error'
                                  ? String(t('copyFailed'))
                                  : String(t('copyRawCode') || 'Copy raw code')
                            }
                            className={cx(
                              'memori-chat--bubble-action-button',
                              'memori-share-button--copy-item',
                              {
                                'memori-share-button--copy-item--success':
                                  copyStatus.raw === 'success',
                                'memori-share-button--copy-item--error':
                                  copyStatus.raw === 'error',
                              }
                            )}
                            icon={
                              copyStatus.raw === 'success' ? (
                                <Check
                                  className="memori-share-button--copy-icon"
                                  aria-hidden
                                  strokeWidth={2.5}
                                />
                              ) : (
                                <Code
                                  className="memori-share-button--copy-icon"
                                  aria-hidden
                                />
                              )
                            }
                            onClick={() =>
                              handleCopyClick('raw', rawMessageText)
                            }
                          />
                        </span>
                      </Tooltip>
                    )}

                    {shouldShowFunctionCacheButton && (
                      <Tooltip
                        {...bubbleAddonTooltipProps}
                        placement="bottom"
                        content={t('toolsDebug') || 'Tools debug'}
                        className="memori-chat--bubble-action-icon memori-chat--bubble-action-icon--debug"
                      >
                        <span className="memori-chat--bubble-addon-tooltip-trigger">
                          <Button
                            variant="ghost"
                            shape="circle"
                            size="sm"
                            className="memori-chat--bubble-action-button"
                            icon={
                              <Bug
                                aria-label={t('toolsDebug') || 'Tools debug'}
                              />
                            }
                            onClick={() => setOpenFunctionCache(true)}
                          />
                        </span>
                      </Tooltip>
                    )}

                    {showFeedback && !!simulateUserPrompt && (
                      <FeedbackButtons
                        memori={memori}
                        className="memori-chat--bubble-feedback"
                        dropdown
                        onNegativeClick={msg => {
                          if (msg) simulateUserPrompt(msg);
                        }}
                      />
                    )}

                    {message.generatedByAI && showAIicon && (
                      <GeneratedByAIMark
                        label={String(t('generatedByAI'))}
                        container={drawerPortalContainer}
                      />
                    )}

                    {showTranslationOriginal &&
                      message.translatedText &&
                      message.translatedText !== message.text && (
                        <Tooltip
                          {...bubbleAddonTooltipProps}
                          placement="bottom"
                          content={`${
                            lang === 'it' ? 'Testo originale' : 'Original text'
                          }: ${stripAllInternalTags(message.text)}`}
                          className="memori-chat--bubble-action-icon memori-chat--bubble-action-icon--ai"
                        >
                          <span className="memori-chat--bubble-addon-tooltip-trigger">
                            <Button
                              variant="ghost"
                              shape="circle"
                              type="button"
                              size="sm"
                              className="memori-chat--bubble-action-button"
                              aria-label={
                                lang === 'it'
                                  ? 'Testo originale'
                                  : 'Original text'
                              }
                              icon={<Languages aria-hidden />}
                            />
                          </span>
                        </Tooltip>
                      )}

                    {!message.fromUser &&
                      message.questionAnswered &&
                      apiUrl &&
                      showWhyThisAnswer && (
                        <Tooltip
                          {...bubbleAddonTooltipProps}
                          placement="bottom"
                          content={t('whyThisAnswer') || 'Why this answer?'}
                        >
                          <span className="memori-chat--bubble-addon-tooltip-trigger">
                            <Button
                              variant="ghost"
                              shape={
                                exposedSourcesCount == null
                                  ? 'circle'
                                  : 'default'
                              }
                              size="sm"
                              active={showingWhyThisAnswer}
                              className={cx(
                                'memori-chat--bubble-action-button',
                                exposedSourcesCount != null &&
                                  'memori-chat--bubble-action-button--sources',
                                exposedSourcesCount === 0 &&
                                  'memori-chat--bubble-action-button--sources-empty'
                              )}
                              onClick={() =>
                                setShowingWhyThisAnswer(open => !open)
                              }
                              aria-label={
                                t('whyThisAnswer') || 'Why this answer?'
                              }
                              icon={<HelpCircle aria-hidden />}
                            >
                              {whyThisAnswerSourcesLabel}
                            </Button>
                          </span>
                        </Tooltip>
                      )}
                  </div>
                )}
              </div>

              {!message.fromUser && (
                <ArtifactHandler
                  isChatlogPanel={isChatlogPanel}
                  message={message}
                />
              )}

              {codeMediaWidgetMedia.length > 0 && (
                <MediaWidget
                  simulateUserPrompt={simulateUserPrompt}
                  media={codeMediaWidgetMedia}
                  sessionID={sessionID}
                  baseUrl={baseUrl}
                  apiUrl={apiUrl}
                  translateTo={translateTo}
                  customMediaRenderer={customMediaRenderer}
                  fromUser={message.fromUser}
                />
              )}
            </div>
          )}

          {message.fromUser && renderUserAvatar()}
        </div>
      </div>

      {/* Document attachments are extracted and passed to Chat.tsx for rendering */}

      {showingWhyThisAnswer && client && (
        <WhyThisAnswer
          client={client}
          visible={showingWhyThisAnswer}
          message={message}
          closeDrawer={() => setShowingWhyThisAnswer(false)}
          sessionID={sessionID}
          isAgentAuthor={!!memori.isGiver}
        />
      )}

      <Modal
        open={openFunctionCache}
        className="memori-chat--function-cache-modal"
        width="80%"
        stacking="stacked"
        title={t('toolsDebug') || 'Tools debug'}
        closable={true}
        onOpenChange={setOpenFunctionCache}
      >
        <div className="memori-chat--function-cache-toolbar">
          <Button
            icon={<Copy aria-hidden />}
            onClick={() =>
              handleCopyClick('functionCache', functionCacheCopyText)
            }
          >
            {copyStatus.functionCache === 'success'
              ? copiedLabel
              : t('copy') || 'Copy'}
          </Button>
        </div>
        <div className="memori-chat--function-cache-entries">
          {functionCacheData?.map(f => (
            <div key={f.mediumID} className="memori-chat--function-cache-entry">
              <h3 className="memori-chat--function-cache-entry-title">
                {f.title}
              </h3>
              <pre className="memori-chat--function-cache-entry-pre">
                {f.content}
              </pre>
            </div>
          ))}
        </div>
      </Modal>
    </>
  );
};

export default ChatBubble;
