/**
 * ArtifactActions Component
 * Provides action buttons for artifact operations (copy, download, print, etc.)
 * Following the project's component patterns and design system
 */

import React, { useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, Dropdown } from '@memori.ai/ui';
import { ArtifactData } from '../../types/artifact.types';
import { Link as LinkIcon, Printer, MoreVertical } from 'lucide-react';
import { CopyButtonWithDropdown } from './';
import { useArtifactDrawerMenuContainer } from '../../useArtifactDrawerMenuContainer';

const ArtifactActions: React.FC<{
  artifact: ArtifactData;
  onCopy: () => void;
  onDownload?: () => void;
  onPrint?: () => void;
  onOpenExternal?: () => void;
  loading: boolean;
  isMobile?: boolean;
}> = ({
  artifact,
  onCopy,
  onDownload,
  onPrint,
  onOpenExternal,
  loading = false,
  isMobile = false,
}) => {
  const { t } = useTranslation();
  const { ref: menuContainerRef, container: menuContainer } =
    useArtifactDrawerMenuContainer();

  /**
   * Get file extension for download
   */
  const getFileExtension = useCallback((mimeType: string): string => {
    const extensions: Record<string, string> = {
      html: 'html',
      json: 'json',
      markdown: 'md',
      css: 'css',
      javascript: 'js',
      typescript: 'ts',
      svg: 'svg',
      xml: 'xml',
      text: 'txt',
      python: 'py',
      java: 'java',
      cpp: 'cpp',
      csharp: 'cs',
      php: 'php',
      ruby: 'rb',
      go: 'go',
      rust: 'rs',
      yaml: 'yml',
      sql: 'sql',
    };
    return extensions[mimeType] || 'txt';
  }, []);

  /**
   * Get MIME type string for downloads
   */
  const getMimeTypeString = useCallback((mimeType: string): string => {
    const mimeTypes: Record<string, string> = {
      html: 'text/html',
      json: 'application/json',
      markdown: 'text/markdown',
      css: 'text/css',
      javascript: 'text/javascript',
      typescript: 'text/typescript',
      svg: 'image/svg+xml',
      xml: 'text/xml',
      text: 'text/plain',
      python: 'text/x-python',
      java: 'text/x-java',
      cpp: 'text/x-c++',
      csharp: 'text/x-csharp',
      php: 'text/x-php',
      ruby: 'text/x-ruby',
      go: 'text/x-go',
      rust: 'text/x-rust',
      yaml: 'text/yaml',
      sql: 'text/x-sql',
    };
    return mimeTypes[mimeType] || 'text/plain';
  }, []);

  /**
   * Handle print action
   */
  const handlePrint = useCallback(() => {
    try {
      const printWindow = window.open('', '_blank');
      if (!printWindow) {
        alert('Popup blocked! Please enable popups to print the artifact.');
        return;
      }

      let printContent: string;
      if (artifact.mimeType === 'html') {
        printContent = artifact.content;
      } else {
        printContent = `
          <!DOCTYPE html>
          <html>
          <head>
            <title>Artifact - ${artifact.mimeType.toUpperCase()}</title>
            <style>
              body { 
                font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace; 
                white-space: pre-wrap; 
                margin: 20px; 
                line-height: 1.4;
              }
              @media print { 
                body { margin: 0; } 
              }
            </style>
          </head>
          <body>${artifact.content
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')}</body>
          </html>
        `;
      }

      printWindow.document.write(printContent);
      printWindow.document.close();

      setTimeout(() => {
        printWindow.print();
        printWindow.close();
      }, 500);

      onPrint?.();
    } catch (error) {
      console.error('Print failed:', error);
    }
  }, [artifact, onPrint]);

  /**
   * Handle external open action
   */
  const handleOpenExternal = useCallback(() => {
    try {
      const mimeType = getMimeTypeString(artifact.mimeType);
      const blob = new Blob([artifact.content], { type: mimeType });
      const url = URL.createObjectURL(blob);

      const externalWindow = window.open(url, '_blank');
      if (!externalWindow) {
        alert(
          'Popup blocked! Please enable popups to open the artifact in a new window.'
        );
        return;
      }

      // Cleanup URL after a delay
      setTimeout(() => {
        URL.revokeObjectURL(url);
      }, 60000);

      onOpenExternal?.();
    } catch (error) {
      console.error('External open failed:', error);
    }
  }, [artifact, getMimeTypeString, onOpenExternal]);

  return (
    <div className="memori-artifact-actions">
      <div className="memori-artifact-actions-row">
        <CopyButtonWithDropdown
          artifact={artifact}
          onCopy={onCopy}
          onDownload={onDownload}
          onPrint={onPrint}
          loading={loading}
          className="memori-artifact-action-btn"
        />
        {isMobile && (
          <Dropdown className="memori-copy-menu-wrapper" ref={menuContainerRef}>
            <Dropdown.Trigger
              showChevron={false}
              className="memori-copy-button-trigger"
              render={(
                props: React.ButtonHTMLAttributes<HTMLButtonElement>
              ) => (
                <Button
                  {...props}
                  disabled={loading}
                  variant="ghost"
                  title="More copy options"
                >
                  <MoreVertical className="memori-artifact-action-icon" />
                </Button>
              )}
            />
            <Dropdown.Menu
              placement="bottom"
              align="end"
              sideOffset={8}
              container={menuContainer ?? undefined}
            >
              <Dropdown.Item
                onClick={handlePrint}
                disabled={loading}
                icon={<Printer />}
                label={t('artifact.print') || 'Print'}
              >
                {t('artifact.print') || 'Print'}
              </Dropdown.Item>
              <Dropdown.Item
                onClick={handleOpenExternal}
                disabled={loading}
                icon={<LinkIcon />}
                label={t('artifact.external') || 'External'}
              >
                {t('artifact.external') || 'External'}
              </Dropdown.Item>
            </Dropdown.Menu>
          </Dropdown>
        )}
      </div>
    </div>
  );
};

export default ArtifactActions;
